"""routing.py: is a project routed through a local Switchyard, and does it answer?

`devil route on` (tools/route.sh) records the route in the project's
.claude/settings.local.json under `_devilRoute`. Two readers need the same answer
the same way: the SessionStart guard (session.py) and the flow's review step
(tools/lib/flow_review.py), so it lives here once. Stdlib only, no kit imports.

Every request here is to http://127.0.0.1 and bypasses HTTP(S)_PROXY: a probe of
the local proxy must not be carried off the machine.
"""

import json
import re
import urllib.request
from pathlib import Path

SETTINGS = ".claude/settings.local.json"
# Caveat: only the http://127.0.0.1:<port> that route.sh writes counts as routed; a URL
# hand-edited to localhost or [::1] reads as not routed, so neither reader acts on it.
LOOPBACK = re.compile(r"http://127\.0\.0\.1:[0-9]{1,5}")
_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))


def routed_url(root):
    """The loopback proxy the project at `root` is routed through, or ""."""
    try:
        cfg = json.loads((Path(root) / SETTINGS).read_text())
    except (OSError, ValueError):
        return ""
    env = cfg.get("env") if isinstance(cfg, dict) and "_devilRoute" in cfg else None
    url = env.get("ANTHROPIC_BASE_URL") if isinstance(env, dict) else None
    return url if isinstance(url, str) and LOOPBACK.fullmatch(url) else ""


def get_json(url, timeout=2):
    """The decoded JSON body of a 200 answer, or None for anything else."""
    try:
        with _OPENER.open(url, timeout=timeout) as resp:
            return json.loads(resp.read()) if resp.status == 200 else None
    except Exception:
        return None


def healthy(url):
    try:
        with _OPENER.open(url + "/health", timeout=2) as resp:
            return resp.status == 200
    except Exception:
        return False
